def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    for i in range(len(s)):
        # Check if the prefix matches
        if s.startswith(prefix, i):
            # Iterate through the substring after the prefix to find the suffix
            for j in range(i + len(prefix), len(s) - len(suffix) + 1):
                if s[j:j + len(suffix)] == suffix:
                    return True
    return False

