def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    rows = len(grid)
    cols = len(grid[0])
    for i in range(rows):
        if i % 2 == 0:
            # Traverse left to right
            for j in range(cols):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse right to left
            for j in range(cols - 1, -1, -1):
                if (cols - 1 - j) % 2 == 0:
                    result.append(grid[i][j])
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    count = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if count[s[i]] == first_digit and count[s[i + 1]] == second_digit:
                return s[i] + s[i + 1]
