def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total_sum = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0:
            is_good = is_good and nums[i] > nums[i - k]
        if i + k < n:
            is_good = is_good and nums[i] > nums[i + k]
        if is_good:
            total_sum += nums[i]
    return total_sum

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:
            before_different = (i == 0 or s[i - 1] != substring[0])
            after_different = (i + k == n or s[i + k] != substring[0])
            if before_different and after_different:
                return True
    return False

