def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # Initialize DP array with 1 (length of subsequence)
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff1 = abs(nums[i] - nums[j])
            if (j == 0 or (dp[j] > 1 and abs(nums[j] - nums[j - 1]) >= diff1)):
                dp[i] = max(dp[i], dp[j] + 1)
        max_length = max(max_length, dp[i])

    return max_length

