def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i-1][(j+1) % 3], dp[i-1][(j+2) % 3])

    half_n = n // 2
    result = float('inf')

    for j in range(3):
        result = min(result, dp[n-1][j] + dp[half_n - 1][(j + 1) % 3] + dp[half_n - 1][(j + 2) % 3])

    return result

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_timestamps = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(args[0])
            online_status[user_id] = False
            offline_timestamps[user_id] = timestamp + 60
        elif event_type == "MESSAGE":
            process_message(args[0], online_status, timestamp, mentions, numberOfUsers, offline_timestamps)

    return mentions


def process_message(mentions_string: str, online_status: List[bool], timestamp: int, mentions: List[int], numberOfUsers: int, offline_timestamps: List[int]) -> None:
    for user_id in range(numberOfUsers):
        if timestamp >= offline_timestamps[user_id]:
            online_status[user_id] = True
    if mentions_string == "ALL":
        for user_id in range(numberOfUsers):
            mentions[user_id] += 1
    elif mentions_string == "HERE":
        for user_id in range(numberOfUsers):
            if online_status[user_id]:
                mentions[user_id] += 1
    else:
        tokens = mentions_string.split()
        for token in tokens:
            if token.startswith("id"):
                user_id = int(token[2:])
                if user_id < numberOfUsers:
                    mentions[user_id] += 1

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    positions = [(0, 0)]
    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
        positions.append((x, y))
        max_distance = max(max_distance, abs(x) + abs(y))

    # Using k changes to maximize Manhattan distance
    for i in range(len(positions)):
        # Calculate total changes available
        distance_with_changes = abs(positions[i][0]) + abs(positions[i][1]) + k
        max_distance = max(max_distance, distance_with_changes)

    return max_distance
